PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?director ?birthDate
WHERE {
  VALUES ?film { 
    dbr:Sabas,_ang_barbaro 
    dbr:Passage_to_Zarahemla 
  }

  # Director (prefer dbp:director)
  OPTIONAL { ?film dbp:director ?directorDBP . }
  OPTIONAL { ?film dbo:director ?directorDBO . }
  BIND ( COALESCE(?directorDBP, ?directorDBO) AS ?director )

  # Director's birth date (prefer dbp:birthDate)
  OPTIONAL { ?director dbp:birthDate ?birthDateDBP . }
  OPTIONAL { ?director dbo:birthDate ?birthDateDBO . }
  BIND ( COALESCE(?birthDateDBP, ?birthDateDBO) AS ?birthDate )
}
LIMIT 100
